/* The Grounded Readings Library, group cath2 (GWG BLD 798). Written by build-readings.py; edit the data, then build again. */
(window.GGReadingsData = window.GGReadingsData || {})["cath2"] = [{"id":"cath-bcp-burial-sentences","title":"I Am the Resurrection and the Life","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"scripture","occasion":["funeral","hope"],"text":"I am the resurrection and the life, saith the Lord: he that believeth in me, though he were dead, yet shall he live: and whosoever liveth and believeth in me shall never die.\n\nI know that my Redeemer liveth, and that he shall stand at the latter day upon the earth. And though after my skin worms destroy this body, yet in my flesh shall I see God: whom I shall see for myself, and mine eyes shall behold, and not another.\n\nWe brought nothing into this world, and it is certain we can carry nothing out. The Lord gave, and the Lord hath taken away; blessed be the name of the Lord.","note":"The opening sentences of the Burial of the Dead, said as the body is carried into the church.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662): The Order for the Burial of the Dead","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States. John 11, Job 19, 1 Timothy 6, Job 1."},{"id":"cath-bcp-man-born-of-woman","title":"In the Midst of Life","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["funeral","grief"],"text":"Man that is born of a woman hath but a short time to live, and is full of misery. He cometh up, and is cut down, like a flower; he fleeth as it were a shadow, and never continueth in one stay.\n\nIn the midst of life we are in death: of whom may we seek for succour, but of thee, O Lord, who for our sins art justly displeased?\n\nYet, O Lord God most holy, O Lord most mighty, O holy and most merciful Saviour, deliver us not into the bitter pains of eternal death.\n\nThou knowest, Lord, the secrets of our hearts; shut not thy merciful ears to our prayer; but spare us, Lord most holy, O God most mighty, O holy and merciful Saviour, thou most worthy Judge eternal, suffer us not, at our last hour, for any pains of death, to fall from thee.","note":"Said at the graveside as the body is made ready to be laid in the earth; some of the most famous words in English.","voice":"brian","source":{"name":"The Book of Common Prayer (1662): The Order for the Burial of the Dead","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-committal-1662","title":"Earth to Earth, Ashes to Ashes (1662)","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["funeral"],"text":"Forasmuch as it hath pleased Almighty God of his great mercy to take unto himself the soul of our dear brother here departed, we therefore commit his body to the ground; earth to earth, ashes to ashes, dust to dust; in sure and certain hope of the Resurrection to eternal life, through our Lord Jesus Christ; who shall change our vile body, that it may be like unto his glorious body, according to the mighty working, whereby he is able to subdue all things to himself.","note":"The committal at the grave, said as earth is cast upon the coffin; say sister and her as fits.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662): The Order for the Burial of the Dead","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-committal-1928","title":"Unto Almighty God We Commend (1928)","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["funeral"],"text":"Unto Almighty God we commend the soul of our brother departed, and we commit his body to the ground; earth to earth, ashes to ashes, dust to dust; looking for the general Resurrection in the last day, and the life of the world to come, through our Lord Jesus Christ; at whose second coming in glorious majesty to judge the world, the earth and the sea shall give up their dead; and the corruptible bodies of those who sleep in him shall be changed, and made like unto his own glorious body; according to the mighty working whereby he is able to subdue all things unto himself.","note":"The American committal at the graveside; also used for ashes and burial at sea with small changes.","voice":"brian","source":{"name":"The Book of Common Prayer (1928, United States): The Order for the Burial of the Dead","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-voice-from-heaven","title":"I Heard a Voice from Heaven","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"scripture","occasion":["funeral","grief","hope"],"text":"I heard a voice from heaven, saying unto me, Write, From henceforth blessed are the dead which die in the Lord: even so saith the Spirit; for they rest from their labours.","note":"Said after the committal; a quiet word that the work of a life is done and rest has come.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662): The Order for the Burial of the Dead","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States. Revelation 14:13."},{"id":"cath-bcp-spirits-of-those","title":"Almighty God, with Whom Still Live the Spirits","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["funeral","grief","gratitude"],"text":"Almighty God, with whom still live the spirits of those who die in the Lord, and with whom the souls of the faithful are in joy and felicity: We give thee hearty thanks for the good examples of all those thy servants, who, having finished their course in faith, do now rest from their labours. And we beseech thee, that we, with all those who are departed in the true faith of thy holy Name, may have our perfect consummation and bliss, both in body and soul, in thy eternal and everlasting glory; through Jesus Christ our Lord. Amen.","note":"A prayer of thanks for a faithful life, said at the burial.","voice":"brian","source":{"name":"The Book of Common Prayer (1928, United States): The Order for the Burial of the Dead","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-father-of-all","title":"Father of All","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian","all"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["grief","funeral","comfort"],"text":"Father of all, we pray to thee for those we love, but see no longer.\nGrant them thy peace; let light perpetual shine upon them;\nand, in thy loving wisdom and almighty power,\nwork in them the good purpose of thy perfect will;\nthrough Jesus Christ our Lord. Amen.","note":"One of the gentlest prayers for those who have died, good for any anniversary or memorial.","voice":"jenny","source":{"name":"The Book of Common Prayer (1928, United States): The Order for the Burial of the Dead","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-remember-thy-servant","title":"From Strength to Strength","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["funeral","grief","hope"],"text":"Remember thy servant, O Lord, according to the favour which thou bearest unto thy people;\nand grant that, increasing in knowledge and love of thee,\nhe may go from strength to strength, in the life of perfect service, in thy heavenly kingdom;\nthrough Jesus Christ our Lord. Amen.","note":"A prayer that the one who has died keeps growing in love; say her as fits.","voice":"brian","source":{"name":"The Book of Common Prayer (1928, United States): The Order for the Burial of the Dead","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-mercies-cannot-be-numbered","title":"O God, Whose Mercies Cannot Be Numbered","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["funeral","grief"],"text":"O God, whose mercies cannot be numbered;\nAccept our prayers on behalf of the soul of thy servant departed,\nand grant him an entrance into the land of light and joy,\nin the fellowship of thy saints;\nthrough Jesus Christ our Lord. Amen.","note":"Said at the burial for the one who has died; say her as fits.","voice":"jenny","source":{"name":"The Book of Common Prayer (1928, United States): The Order for the Burial of the Dead","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-days-without-end","title":"O God, Whose Days Are Without End","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["funeral","grief"],"text":"O God, whose days are without end, and whose mercies cannot be numbered;\nMake us, we beseech thee, deeply sensible of the shortness and uncertainty of human life;\nand let thy Holy Spirit lead us in holiness and righteousness all our days:\nthat, when we shall have served thee in our generation,\nwe may be gathered unto our fathers, having the testimony of a good conscience;\nin the communion of the Catholic Church;\nin the confidence of a certain faith;\nin the comfort of a reasonable, religious, and holy hope;\nin favour with thee our God, and in perfect charity with the world.\nAll which we ask through Jesus Christ our Lord. Amen.","note":"A prayer for the living at a funeral, for a life well finished; drawn from Jeremy Taylor.","voice":"brian","source":{"name":"The Book of Common Prayer (1928, United States): The Order for the Burial of the Dead","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain. Adapted from Jeremy Taylor (died 1667)."},{"id":"cath-bcp-merciful-god-father","title":"O Merciful God, the Father of Our Lord","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["funeral","hope"],"text":"O merciful God, the Father of our Lord Jesus Christ, who is the resurrection and the life; in whom whosoever believeth shall live, though he die; and whosoever liveth, and believeth in him, shall not die eternally; who also hath taught us, by his holy Apostle Saint Paul, not to be sorry, as men without hope, for them that sleep in him:\n\nWe meekly beseech thee, O Father, to raise us from the death of sin unto the life of righteousness; that, when we shall depart this life, we may rest in him, as our hope is this our brother doth; and that, at the general Resurrection in the last day, we may be found acceptable in thy sight; and receive that blessing, which thy well beloved Son shall then pronounce to all that love and fear thee, saying, Come, ye blessed children of my Father, receive the kingdom prepared for you from the beginning of the world.\n\nGrant this, we beseech thee, O merciful Father, through Jesus Christ, our Mediator and Redeemer. Amen.","note":"The closing collect of the burial service.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662): The Order for the Burial of the Dead","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-god-of-spirits-1928","title":"Multiply to Those Who Rest","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["funeral","grief","hope"],"text":"O Almighty God, the God of the spirits of all flesh, who by a voice from heaven didst proclaim, Blessed are the dead who die in the Lord:\nMultiply, we beseech thee, to those who rest in Jesus, the manifold blessings of thy love,\nthat the good work which thou didst begin in them may be perfected unto the day of Jesus Christ.\nAnd of thy mercy, O heavenly Father, vouchsafe that we, who now serve thee here on earth,\nmay at last, together with them, be found meet to be partakers of the inheritance of the saints in light;\nfor the sake of the same thy Son Jesus Christ our Lord. Amen.","note":"A prayer that joins the living and the dead in one hope.","voice":"brian","source":{"name":"The Book of Common Prayer (1928, United States): The Order for the Burial of the Dead","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-god-of-peace","title":"The God of Peace","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"blessing","occasion":["funeral","blessing","peace"],"text":"The God of peace, who brought again from the dead our Lord Jesus Christ, that great Shepherd of the sheep, through the blood of the everlasting covenant: Make you perfect in every good work to do his will, working in you that which is well pleasing in his sight; through Jesus Christ, to whom be glory for ever and ever. Amen.","note":"The blessing that closes the burial service, from Hebrews 13.","voice":"jenny","source":{"name":"The Book of Common Prayer (1928, United States): The Order for the Burial of the Dead","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-rest-eternal","title":"Rest Eternal Grant Him","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["funeral","grief","dying"],"text":"Rest eternal grant him, O Lord;\nAnd let light perpetual shine upon him.","note":"The versicle and response the 1928 book restored to the Episcopal burial; say her or them as fits.","voice":"brian","source":{"name":"The Book of Common Prayer (1928, United States): The Order for the Burial of the Dead","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-psalm-90","title":"Lord, Thou Hast Been Our Refuge (Psalm 90)","by":"The Book of Common Prayer (1662), Coverdale Psalter","tr":"Miles Coverdale","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"scripture","occasion":["funeral","grief"],"text":"Lord, thou hast been our refuge: from one generation to another.\nBefore the mountains were brought forth, or ever the earth and the world were made: thou art God from everlasting, and world without end.\nThou turnest man to destruction: again thou sayest, Come again, ye children of men.\nFor a thousand years in thy sight are but as yesterday: seeing that is past as a watch in the night.\nAs soon as thou scatterest them they are even as a sleep: and fade away suddenly like the grass.\nIn the morning it is green, and groweth up: but in the evening it is cut down, dried up, and withered.\n\nThe days of our age are threescore years and ten; and though men be so strong that they come to fourscore years: yet is their strength then but labour and sorrow; so soon passeth it away, and we are gone.\n\nSo teach us to number our days: that we may apply our hearts unto wisdom.","note":"One of the two psalms of the burial service, in the beloved Coverdale wording.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662): The Psalter","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"Miles Coverdale translation, 1535, as printed in the Book of Common Prayer, 1662; public domain."},{"id":"cath-bcp-psalm-23","title":"The Lord Is My Shepherd (Coverdale)","by":"The Book of Common Prayer (1662), Coverdale Psalter","tr":"Miles Coverdale","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"scripture","occasion":["funeral","comfort","dying"],"text":"The Lord is my shepherd: therefore can I lack nothing.\nHe shall feed me in a green pasture: and lead me forth beside the waters of comfort.\nHe shall convert my soul: and bring me forth in the paths of righteousness, for his Name's sake.\nYea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff comfort me.\nThou shalt prepare a table before me against them that trouble me: thou hast anointed my head with oil, and my cup shall be full.\nBut thy loving kindness and mercy shall follow me all the days of my life: and I will dwell in the house of the Lord for ever.","note":"Psalm 23 as Anglicans have prayed it for nearly five hundred years: beside the waters of comfort.","voice":"brian","source":{"name":"The Book of Common Prayer (1662): The Psalter","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"Miles Coverdale translation, 1535, as printed in the Book of Common Prayer, 1662; public domain."},{"id":"cath-bcp-psalm-121","title":"I Will Lift Up Mine Eyes (Coverdale)","by":"The Book of Common Prayer (1662), Coverdale Psalter","tr":"Miles Coverdale","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"scripture","occasion":["comfort","dying","blessing"],"text":"I will lift up mine eyes unto the hills: from whence cometh my help.\nMy help cometh even from the Lord: who hath made heaven and earth.\nHe will not suffer thy foot to be moved: and he that keepeth thee will not sleep.\nBehold, he that keepeth Israel: shall neither slumber nor sleep.\nThe Lord himself is thy keeper: the Lord is thy defence upon thy right hand;\nSo that the sun shall not burn thee by day: neither the moon by night.\nThe Lord shall preserve thee from all evil: yea, it is even he that shall keep thy soul.\nThe Lord shall preserve thy going out, and thy coming in: from this time forth for evermore.","note":"The traveler's psalm, prayed for journeys and for the last journey home.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662): The Psalter","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"Miles Coverdale translation, 1535, as printed in the Book of Common Prayer, 1662; public domain."},{"id":"cath-bcp-psalm-100","title":"O Be Joyful in the Lord (Psalm 100)","by":"The Book of Common Prayer (1662), Coverdale Psalter","tr":"Miles Coverdale","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"scripture","occasion":["gratitude","celebration","morning"],"text":"O be joyful in the Lord, all ye lands: serve the Lord with gladness, and come before his presence with a song.\nBe ye sure that the Lord he is God: it is he that hath made us, and not we ourselves; we are his people, and the sheep of his pasture.\nO go your way into his gates with thanksgiving, and into his courts with praise: be thankful unto him, and speak good of his Name.\nFor the Lord is gracious, his mercy is everlasting: and his truth endureth from generation to generation.","note":"The Jubilate, sung at Morning Prayer; a glad psalm for a celebration of life.","voice":"brian","source":{"name":"The Book of Common Prayer (1662): The Order for Morning Prayer","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"Miles Coverdale translation, 1535, as printed in the Book of Common Prayer, 1662; public domain."},{"id":"cath-donne-one-equal-light","title":"One Equal Light","by":"John Donne","year":1640,"trad":["episcopal","christian","all"],"type":"reflection","occasion":["funeral","hope","dying"],"text":"And into that gate they shall enter, and in that house they shall dwell, where there shall be no cloud nor sun, no darkness nor dazzling, but one equal light; no noise nor silence, but one equal music; no fears nor hopes, but one equal possession; no foes nor friends, but an equal communion and identity; no ends nor beginnings, but one equal eternity.","note":"From a sermon the poet and priest John Donne preached at Whitehall in 1628, a vision of heaven read at many funerals.","voice":"jenny","source":{"name":"John Donne, LXXX Sermons (1640), Internet Archive","url":"https://archive.org/search?query=Donne+LXXX+Sermons+1640"},"rights":"pd","pd":"Preached 1628, printed 1640; Donne died 1631; public domain. Spelling modernized.","denom":[]},{"id":"cath-ken-evening-hymn","title":"Glory to Thee, My God, This Night","by":"Thomas Ken","year":1695,"trad":["episcopal","christian"],"type":"hymn","occasion":["evening","dying","peace"],"text":"Glory to thee, my God, this night\nFor all the blessings of the light;\nKeep me, O keep me, King of kings,\nBeneath thine own almighty wings.\n\nForgive me, Lord, for thy dear Son,\nThe ill that I this day have done,\nThat with the world, myself, and thee,\nI, ere I sleep, at peace may be.\n\nTeach me to live, that I may dread\nThe grave as little as my bed;\nTeach me to die, that so I may\nRise glorious at the awful day.\n\nO may my soul on thee repose,\nAnd may sweet sleep mine eyelids close,\nSleep that may me more vigorous make\nTo serve my God when I awake.\n\nPraise God, from whom all blessings flow;\nPraise him, all creatures here below;\nPraise him above, ye heavenly host;\nPraise Father, Son, and Holy Ghost.","note":"Bishop Ken's evening hymn, ending with the Doxology sung in churches everywhere.","voice":"brian","source":{"name":"Hymnary.org","url":"https://hymnary.org/search?qu=Glory+to+thee+my+God+this+night"},"rights":"pd","pd":"Written about 1674, printed 1695; Ken died 1711; public domain.","denom":[]},{"id":"cath-bcp-easter-anthems","title":"Christ Our Passover","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"scripture","occasion":["season","hope","celebration"],"text":"Christ our passover is sacrificed for us: therefore let us keep the feast;\nNot with the old leaven, nor with the leaven of malice and wickedness: but with the unleavened bread of sincerity and truth.\n\nChrist being raised from the dead dieth no more: death hath no more dominion over him.\nFor in that he died, he died unto sin once: but in that he liveth, he liveth unto God.\nLikewise reckon ye also yourselves to be dead indeed unto sin: but alive unto God through Jesus Christ our Lord.\n\nChrist is risen from the dead: and become the first fruits of them that slept.\nFor since by man came death: by man came also the resurrection of the dead.\nFor as in Adam all die: even so in Christ shall all be made alive.","note":"The Easter Anthems, sung on Easter morning in place of the Venite.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662): Collects, Epistles, and Gospels: Easter Day","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States. 1 Corinthians 5, Romans 6, 1 Corinthians 15."},{"id":"cath-bcp-dearly-beloved","title":"Dearly Beloved","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"reflection","occasion":["wedding"],"text":"Dearly beloved, we are gathered together here in the sight of God, and in the face of this company, to join together this Man and this Woman in holy Matrimony; which is an honourable estate, instituted of God, signifying unto us the mystical union that is betwixt Christ and his Church: which holy estate Christ adorned and beautified with his presence and first miracle that he wrought in Cana of Galilee, and is commended of Saint Paul to be honourable among all men: and therefore is not by any to be entered into unadvisedly or lightly; but reverently, discreetly, advisedly, soberly, and in the fear of God. Into this holy estate these two persons present come now to be joined.","note":"The opening words of the traditional wedding, still asked for by many couples.","voice":"brian","source":{"name":"The Book of Common Prayer (1928, United States): The Form of Solemnization of Matrimony","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-wedding-vows","title":"To Have and to Hold","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian","all"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["wedding"],"text":"I take thee to my wedded wife, to have and to hold from this day forward, for better for worse, for richer for poorer, in sickness and in health, to love and to cherish, till death us do part, according to God's holy ordinance; and thereto I plight thee my troth.\n\nI take thee to my wedded husband, to have and to hold from this day forward, for better for worse, for richer for poorer, in sickness and in health, to love and to cherish, till death us do part, according to God's holy ordinance; and thereto I give thee my troth.","note":"The classic wedding vows, each person saying their own name and their partner's at the start.","voice":"jenny","source":{"name":"The Book of Common Prayer (1928, United States): The Form of Solemnization of Matrimony","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-ring","title":"With This Ring","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["wedding"],"text":"With this Ring I thee wed:\nIn the Name of the Father, and of the Son, and of the Holy Ghost. Amen.","note":"Said while placing the ring on the finger.","voice":"brian","source":{"name":"The Book of Common Prayer (1928, United States): The Form of Solemnization of Matrimony","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-living-faithfully","title":"Living Faithfully Together","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["wedding","blessing"],"text":"O Eternal God, Creator and Preserver of all mankind, Giver of all spiritual grace, the Author of everlasting life;\nSend thy blessing upon these thy servants, this man and this woman, whom we bless in thy Name;\nthat they, living faithfully together, may surely perform and keep the vow and covenant betwixt them made,\nwhereof this Ring given and received is a token and pledge,\nand may ever remain in perfect love and peace together,\nand live according to thy laws; through Jesus Christ our Lord. Amen.","note":"The prayer after the vows and rings.","voice":"jenny","source":{"name":"The Book of Common Prayer (1928, United States): The Form of Solemnization of Matrimony","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-gift-of-children","title":"The Heritage of Children","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["wedding","birth"],"text":"O Almighty God, Creator of mankind, who only art the well spring of life;\nBestow upon these thy servants, if it be thy will, the gift and heritage of children;\nand grant that they may see their children brought up in thy faith and fear,\nto the honour and glory of thy Name; through Jesus Christ our Lord. Amen.","note":"An optional prayer in the wedding, for the gift of children.","voice":"brian","source":{"name":"The Book of Common Prayer (1928, United States): The Form of Solemnization of Matrimony","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-what-god-joined","title":"Those Whom God Hath Joined","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"blessing","occasion":["wedding"],"text":"Those whom God hath joined together let no man put asunder.\n\nForasmuch as these two have consented together in holy wedlock, and have witnessed the same before God and this company, and thereto have given and pledged their troth, each to the other, and have declared the same by giving and receiving a Ring, and by joining hands; I pronounce that they are Man and Wife, In the Name of the Father, and of the Son, and of the Holy Ghost. Amen.","note":"The pronouncement, as the couple's joined hands are held.","voice":"jenny","source":{"name":"The Book of Common Prayer (1928, United States): The Form of Solemnization of Matrimony","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-marriage-blessing","title":"A Blessing for the Married Couple","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"blessing","occasion":["wedding","blessing"],"text":"God the Father, God the Son, God the Holy Ghost, bless, preserve, and keep you;\nthe Lord mercifully with his favour look upon you,\nand so fill you with all spiritual benediction and grace,\nthat ye may so live together in this life,\nthat in the world to come ye may have life everlasting. Amen.","note":"The final blessing of the wedding.","voice":"brian","source":{"name":"The Book of Common Prayer (1928, United States): The Form of Solemnization of Matrimony","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-collect-for-purity","title":"The Collect for Purity","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["daily","morning"],"text":"Almighty God, unto whom all hearts be open, all desires known, and from whom no secrets are hid:\nCleanse the thoughts of our hearts by the inspiration of thy Holy Spirit,\nthat we may perfectly love thee, and worthily magnify thy holy Name;\nthrough Christ our Lord. Amen.","note":"The prayer that opens the Holy Communion, from the eleventh century Sarum rite.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662): The Order for the Administration of the Lord's Supper","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-lighten-our-darkness","title":"Lighten Our Darkness","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian","all"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["evening","comfort","peace"],"text":"Lighten our darkness, we beseech thee, O Lord;\nand by thy great mercy defend us from all perils and dangers of this night;\nfor the love of thy only Son, our Saviour, Jesus Christ. Amen.","note":"The Third Collect at Evening Prayer, for Aid against all Perils; a perfect prayer for a long night watch.","voice":"brian","source":{"name":"The Book of Common Prayer (1662): The Order for Evening Prayer","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-peace-world-cannot-give","title":"That Peace Which the World Cannot Give","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["evening","peace"],"text":"O God, from whom all holy desires, all good counsels, and all just works do proceed:\nGive unto thy servants that peace which the world cannot give;\nthat both our hearts may be set to obey thy commandments,\nand also that by thee we being defended from the fear of our enemies\nmay pass our time in rest and quietness;\nthrough the merits of Jesus Christ our Saviour. Amen.","note":"The Second Collect at Evening Prayer, for Peace.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662): The Order for Evening Prayer","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-beginning-of-this-day","title":"Safely Brought to the Beginning of This Day","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["morning","daily"],"text":"O Lord, our heavenly Father, Almighty and everlasting God, who hast safely brought us to the beginning of this day:\nDefend us in the same with thy mighty power;\nand grant that this day we fall into no sin, neither run into any kind of danger;\nbut that all our doings may be ordered by thy governance,\nto do always that is righteous in thy sight;\nthrough Jesus Christ our Lord. Amen.","note":"The Third Collect at Morning Prayer, for Grace.","voice":"brian","source":{"name":"The Book of Common Prayer (1662): The Order for Morning Prayer","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-general-thanksgiving","title":"The General Thanksgiving","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["gratitude","funeral","celebration"],"text":"Almighty God, Father of all mercies, we thine unworthy servants do give thee most humble and hearty thanks for all thy goodness and loving kindness to us, and to all men.\nWe bless thee for our creation, preservation, and all the blessings of this life; but above all for thine inestimable love in the redemption of the world by our Lord Jesus Christ; for the means of grace, and for the hope of glory.\nAnd, we beseech thee, give us that due sense of all thy mercies, that our hearts may be unfeignedly thankful, and that we shew forth thy praise, not only with our lips, but in our lives; by giving up ourselves to thy service, and by walking before thee in holiness and righteousness all our days;\nthrough Jesus Christ our Lord, to whom with thee and the Holy Ghost be all honour and glory, world without end. Amen.","note":"A prayer of thanks for all of life, lovely at a celebration of life or a thanksgiving meal.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662): Prayers and Thanksgivings upon Several Occasions","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States. Written by Edward Reynolds, 1661."},{"id":"cath-bcp-general-confession","title":"The General Confession","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["forgiveness","daily"],"text":"Almighty and most merciful Father; We have erred, and strayed from thy ways like lost sheep. We have followed too much the devices and desires of our own hearts. We have offended against thy holy laws. We have left undone those things which we ought to have done; And we have done those things which we ought not to have done; And there is no health in us.\n\nBut thou, O Lord, have mercy upon us, miserable offenders. Spare thou them, O God, which confess their faults. Restore thou them that are penitent; According to thy promises declared unto mankind in Christ Jesu our Lord.\n\nAnd grant, O most merciful Father, for his sake; That we may hereafter live a godly, righteous, and sober life, To the glory of thy holy Name. Amen.","note":"The confession at Morning and Evening Prayer, a way to set down what weighs on the heart.","voice":"brian","source":{"name":"The Book of Common Prayer (1662): The Order for Morning Prayer","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-chrysostom","title":"A Prayer of Saint Chrysostom","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","orthodox","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["daily","peace"],"text":"Almighty God, who hast given us grace at this time with one accord to make our common supplications unto thee;\nand dost promise that when two or three are gathered together in thy Name thou wilt grant their requests:\nFulfil now, O Lord, the desires and petitions of thy servants, as may be most expedient for them;\ngranting us in this world knowledge of thy truth, and in the world to come life everlasting. Amen.","note":"From the Greek liturgy of Saint John Chrysostom, closing Morning and Evening Prayer; a bridge between East and West.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662): The Order for Evening Prayer","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States. From the Byzantine Liturgy, translated by Thomas Cranmer, 1544."},{"id":"cath-bcp-the-grace","title":"The Grace","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"blessing","occasion":["blessing","daily"],"text":"The grace of our Lord Jesus Christ, and the love of God, and the fellowship of the Holy Ghost, be with us all evermore. Amen.","note":"Said together at the close of a prayer gathering, from 2 Corinthians 13.","voice":"brian","source":{"name":"The Book of Common Prayer (1662): The Order for Evening Prayer","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-peace-of-god","title":"The Peace of God","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian","all"],"denom":["anglican","bcp1662"],"type":"blessing","occasion":["blessing","funeral","peace"],"text":"The peace of God, which passeth all understanding, keep your hearts and minds in the knowledge and love of God, and of his Son Jesus Christ our Lord:\nAnd the blessing of God Almighty, the Father, the Son, and the Holy Ghost, be amongst you and remain with you always. Amen.","note":"The blessing at the end of the Holy Communion, often used to close a funeral or memorial.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662): The Order for the Administration of the Lord's Supper","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-prevent-us","title":"Prevent Us, O Lord","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["daily","morning"],"text":"Prevent us, O Lord, in all our doings with thy most gracious favour,\nand further us with thy continual help;\nthat in all our works begun, continued, and ended in thee,\nwe may glorify thy holy Name, and finally by thy mercy obtain everlasting life;\nthrough Jesus Christ our Lord. Amen.","note":"A prayer to begin any work; here prevent has its old meaning, go before.","voice":"brian","source":{"name":"The Book of Common Prayer (1662): The Order for the Administration of the Lord's Supper","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-all-saints","title":"Knit Together in One Communion","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["season","grief","funeral"],"text":"O Almighty God, who hast knit together thine elect in one communion and fellowship, in the mystical body of thy Son Christ our Lord:\nGrant us grace so to follow thy blessed Saints in all virtuous and godly living,\nthat we may come to those unspeakable joys, which thou hast prepared for them that unfeignedly love thee;\nthrough Jesus Christ our Lord. Amen.","note":"The collect for All Saints Day, November 1, when many churches read the names of those who died that year.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662): Collects, Epistles, and Gospels: All Saints Day","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-protector","title":"The Protector of All That Trust in Thee","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["comfort","daily"],"text":"O God, the protector of all that trust in thee, without whom nothing is strong, nothing is holy:\nIncrease and multiply upon us thy mercy;\nthat, thou being our ruler and guide, we may so pass through things temporal,\nthat we finally lose not the things eternal:\nGrant this, O heavenly Father, for Jesus Christ's sake our Lord. Amen.","note":"The collect for the Fourth Sunday after Trinity.","voice":"brian","source":{"name":"The Book of Common Prayer (1662): Collects, Epistles, and Gospels: Fourth Sunday after Trinity","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-such-good-things","title":"Such Good Things as Pass Understanding","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["hope","funeral"],"text":"O God, who hast prepared for them that love thee such good things as pass man's understanding:\nPour into our hearts such love toward thee,\nthat we, loving thee above all things, may obtain thy promises,\nwhich exceed all that we can desire;\nthrough Jesus Christ our Lord. Amen.","note":"The collect for the Sixth Sunday after Trinity, a favorite at funerals.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662): Collects, Epistles, and Gospels: Sixth Sunday after Trinity","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-advent","title":"The Armour of Light","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["season","hope"],"text":"Almighty God, give us grace that we may cast away the works of darkness, and put upon us the armour of light, now in the time of this mortal life, in which thy Son Jesus Christ came to visit us in great humility;\nthat in the last day, when he shall come again in his glorious Majesty to judge both the quick and the dead, we may rise to the life immortal,\nthrough him who liveth and reigneth with thee and the Holy Ghost, now and ever. Amen.","note":"The collect for the First Sunday in Advent, prayed through the weeks before Christmas.","voice":"brian","source":{"name":"The Book of Common Prayer (1662): Collects, Epistles, and Gospels: First Sunday in Advent","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-christmas","title":"Born of a Pure Virgin","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["season","birth","celebration"],"text":"Almighty God, who hast given us thy only begotten Son to take our nature upon him, and as at this time to be born of a pure Virgin:\nGrant that we being regenerate, and made thy children by adoption and grace, may daily be renewed by thy Holy Spirit;\nthrough the same our Lord Jesus Christ, who liveth and reigneth with thee and the same Spirit, ever one God, world without end. Amen.","note":"The collect for Christmas Day.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662): Collects, Epistles, and Gospels: Christmas Day","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-ash-wednesday","title":"Who Hatest Nothing That Thou Hast Made","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["season","forgiveness"],"text":"Almighty and everlasting God, who hatest nothing that thou hast made, and dost forgive the sins of all them that are penitent:\nCreate and make in us new and contrite hearts, that we worthily lamenting our sins, and acknowledging our wretchedness,\nmay obtain of thee, the God of all mercy, perfect remission and forgiveness;\nthrough Jesus Christ our Lord. Amen.","note":"The collect for Ash Wednesday, prayed every day of Lent.","voice":"brian","source":{"name":"The Book of Common Prayer (1662): Collects, Epistles, and Gospels: Ash Wednesday","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-easter-collect","title":"The Gate of Everlasting Life","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["season","hope","funeral"],"text":"Almighty God, who through thine only begotten Son Jesus Christ hast overcome death, and opened unto us the gate of everlasting life:\nWe humbly beseech thee, that, as by thy special grace preventing us thou dost put into our minds good desires,\nso by thy continual help we may bring the same to good effect;\nthrough Jesus Christ our Lord, who liveth and reigneth with thee and the Holy Ghost, ever one God, world without end. Amen.","note":"The collect for Easter Day.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662): Collects, Epistles, and Gospels: Easter Day","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-michael-and-angels","title":"Saint Michael and All Angels","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["comfort","dying"],"text":"O everlasting God, who hast ordained and constituted the services of Angels and men in a wonderful order:\nMercifully grant, that as thy holy Angels always do thee service in heaven,\nso by thy appointment they may succour and defend us on earth;\nthrough Jesus Christ our Lord. Amen.","note":"The collect for Michaelmas, September 29; comforting when a family asks for angels to keep watch.","voice":"brian","source":{"name":"The Book of Common Prayer (1662): Collects, Epistles, and Gospels: Saint Michael and All Angels","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-te-deum","title":"We Praise Thee, O God (Te Deum)","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","catholic","christian"],"denom":["anglican","bcp1662"],"type":"hymn","occasion":["celebration","gratitude","funeral"],"text":"We praise thee, O God: we acknowledge thee to be the Lord.\nAll the earth doth worship thee: the Father everlasting.\nTo thee all Angels cry aloud: the Heavens, and all the Powers therein.\nTo thee Cherubin and Seraphin: continually do cry,\nHoly, Holy, Holy: Lord God of Sabaoth;\nHeaven and earth are full of the Majesty: of thy glory.\nThe glorious company of the Apostles: praise thee.\nThe goodly fellowship of the Prophets: praise thee.\nThe noble army of Martyrs: praise thee.\nThe holy Church throughout all the world: doth acknowledge thee;\nThe Father: of an infinite Majesty;\nThine honourable, true: and only Son;\nAlso the Holy Ghost: the Comforter.\n\nThou art the King of Glory: O Christ.\nThou art the everlasting Son: of the Father.\nWhen thou hadst overcome the sharpness of death: thou didst open the Kingdom of Heaven to all believers.\nThou sittest at the right hand of God: in the glory of the Father.\nWe therefore pray thee, help thy servants: whom thou hast redeemed with thy precious blood.\nMake them to be numbered with thy Saints: in glory everlasting.\n\nO Lord, save thy people: and bless thine heritage.\nGovern them: and lift them up for ever.\nDay by day: we magnify thee;\nAnd we worship thy Name: ever world without end.\nO Lord, in thee have I trusted: let me never be confounded.","translit":"Te Deum laudamus","note":"The great hymn of praise of the Western church, sung at Morning Prayer and at thanksgivings; a selection.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662): The Order for Morning Prayer","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States. Latin hymn, fourth century."},{"id":"cath-bcp-gloria","title":"Glory Be to God on High","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"hymn","occasion":["celebration","gratitude","season"],"text":"Glory be to God on high, and in earth peace, good will towards men.\nWe praise thee, we bless thee, we worship thee, we glorify thee, we give thanks to thee for thy great glory, O Lord God, heavenly King, God the Father Almighty.\n\nO Lord, the only begotten Son Jesu Christ; O Lord God, Lamb of God, Son of the Father, that takest away the sins of the world, have mercy upon us.\nThou that takest away the sins of the world, receive our prayer.\nThou that sittest at the right hand of God the Father, have mercy upon us.\n\nFor thou only art holy; thou only art the Lord; thou only, O Christ, with the Holy Ghost, art most high in the glory of God the Father. Amen.","translit":"Gloria in excelsis Deo","note":"The angels' song from Bethlehem, grown into the great hymn sung at the Holy Communion.","voice":"brian","source":{"name":"The Book of Common Prayer (1662): The Order for the Administration of the Lord's Supper","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-benedicite","title":"O All Ye Works of the Lord (Benedicite)","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","catholic","nature","christian"],"denom":["anglican","bcp1662"],"type":"hymn","occasion":["nature","gratitude","morning"],"text":"O all ye Works of the Lord, bless ye the Lord: praise him, and magnify him for ever.\nO ye Angels of the Lord, bless ye the Lord: praise him, and magnify him for ever.\nO ye Sun and Moon, bless ye the Lord: praise him, and magnify him for ever.\nO ye Stars of Heaven, bless ye the Lord: praise him, and magnify him for ever.\nO ye Showers and Dew, bless ye the Lord: praise him, and magnify him for ever.\nO ye Winds of God, bless ye the Lord: praise him, and magnify him for ever.\nO ye Winter and Summer, bless ye the Lord: praise him, and magnify him for ever.\nO ye Ice and Snow, bless ye the Lord: praise him, and magnify him for ever.\nO ye Nights and Days, bless ye the Lord: praise him, and magnify him for ever.\nO ye Light and Darkness, bless ye the Lord: praise him, and magnify him for ever.\nO let the Earth bless the Lord: yea, let it praise him, and magnify him for ever.\nO ye Mountains and Hills, bless ye the Lord: praise him, and magnify him for ever.\nO all ye Green Things upon the Earth, bless ye the Lord: praise him, and magnify him for ever.\nO ye Wells, bless ye the Lord: praise him, and magnify him for ever.\nO ye Seas and Floods, bless ye the Lord: praise him, and magnify him for ever.\nO ye Whales, and all that move in the Waters, bless ye the Lord: praise him, and magnify him for ever.\nO all ye Fowls of the Air, bless ye the Lord: praise him, and magnify him for ever.\nO all ye Beasts and Cattle, bless ye the Lord: praise him, and magnify him for ever.\nO ye Children of Men, bless ye the Lord: praise him, and magnify him for ever.","translit":"Benedicite, omnia opera Domini","note":"The Song of the Three Young Men in the fiery furnace, all creation praising God; a joy for anyone who loved the outdoors. A selection of verses.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662): The Order for Morning Prayer","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States. From the Song of the Three Children."},{"id":"cath-bcp-great-litany","title":"From the Great Litany","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"litany","occasion":["comfort","healing","peace"],"text":"That it may please thee to succour, help, and comfort, all that are in danger, necessity, and tribulation;\nWe beseech thee to hear us, good Lord.\n\nThat it may please thee to preserve all that travel by land or by water, all women labouring of child, all sick persons, and young children; and to shew thy pity upon all prisoners and captives;\nWe beseech thee to hear us, good Lord.\n\nThat it may please thee to defend, and provide for, the fatherless children, and widows, and all that are desolate and oppressed;\nWe beseech thee to hear us, good Lord.\n\nThat it may please thee to have mercy upon all men;\nWe beseech thee to hear us, good Lord.\n\nThat it may please thee to forgive our enemies, persecutors, and slanderers, and to turn their hearts;\nWe beseech thee to hear us, good Lord.\n\nThat it may please thee to give and preserve to our use the kindly fruits of the earth, so as in due time we may enjoy them;\nWe beseech thee to hear us, good Lord.","note":"Thomas Cranmer's Litany of 1544, the first service ever written in English; a selection of its petitions.","voice":"brian","source":{"name":"The Book of Common Prayer (1662): The Litany","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States. Written by Thomas Cranmer, 1544."},{"id":"cath-bcp-small-hope","title":"For a Sick Person Near the End","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["dying","healing"],"text":"O Father of mercies, and God of all comfort, our only help in time of need:\nWe fly unto thee for succour in behalf of this thy servant, here lying under thy hand in great weakness of body.\nLook graciously upon him, O Lord; and the more the outward man decayeth, strengthen him, we beseech thee, so much the more continually with thy grace and Holy Spirit in the inner man.\nGive him unfeigned repentance for all the errors of his life past, and stedfast faith in thy Son Jesus;\nthat his sins may be done away by thy mercy, and his pardon sealed in heaven;\nthrough the same thy Son, our Lord and Saviour. Amen.","note":"From the Visitation of the Sick: the more the outward body weakens, the stronger the inner life; say her as fits.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662): The Order for the Visitation of the Sick","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-strong-tower","title":"A Most Strong Tower","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"blessing","occasion":["healing","dying","blessing"],"text":"The Almighty Lord, who is a most strong tower to all them that put their trust in him, to whom all things in heaven, in earth, and under the earth, do bow and obey:\nBe now and evermore thy defence; and make thee know and feel, that there is none other Name under heaven given to man, in whom, and through whom, thou mayest receive health and salvation, but only the Name of our Lord Jesus Christ. Amen.","note":"A blessing for the sick from the Visitation of the Sick.","voice":"brian","source":{"name":"The Book of Common Prayer (1662): The Order for the Visitation of the Sick","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-gods-gracious-mercy","title":"Unto God's Gracious Mercy","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian","all"],"denom":["anglican","bcp1662"],"type":"blessing","occasion":["dying","blessing","healing"],"text":"Unto God's gracious mercy and protection we commit thee.\nThe Lord bless thee, and keep thee.\nThe Lord make his face to shine upon thee, and be gracious unto thee.\nThe Lord lift up his countenance upon thee, and give thee peace, both now and evermore. Amen.","note":"The closing blessing of the Visitation of the Sick, built on the ancient priestly blessing of Numbers 6.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662): The Order for the Visitation of the Sick","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-under-affliction","title":"For a Person under Affliction","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["comfort","grief","healing"],"text":"O merciful God, and heavenly Father, who hast taught us in thy holy Word that thou dost not willingly afflict or grieve the children of men;\nLook with pity, we beseech thee, upon the sorrows of thy servant for whom our prayers are desired.\nIn thy wisdom thou hast seen fit to visit him with trouble, and to bring distress upon him.\nRemember him, O Lord, in mercy; endue his soul with patience under his affliction, and with resignation to thy blessed will;\ncomfort him with a sense of thy goodness; lift up thy countenance upon him, and give him peace;\nthrough Jesus Christ our Lord. Amen.","note":"A prayer for anyone carrying a heavy sorrow; say her as fits.","voice":"brian","source":{"name":"The Book of Common Prayer (1928, United States): Prayers and Thanksgivings","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-quiet-confidence","title":"For Quiet Confidence","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian","all"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["peace","comfort","evening"],"text":"O God of peace, who hast taught us that in returning and rest we shall be saved, in quietness and in confidence shall be our strength;\nBy the might of thy Spirit lift us, we pray thee, to thy presence,\nwhere we may be still and know that thou art God;\nthrough Jesus Christ our Lord. Amen.","note":"A prayer for stillness from Isaiah 30 and Psalm 46, lovely before sleep or a hard conversation.","voice":"jenny","source":{"name":"The Book of Common Prayer (1928, United States): Forms of Prayer to Be Used in Families","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-life-of-all-who-live","title":"The Life of All Who Live","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["evening","peace","home"],"text":"O God, the life of all who live, the light of the faithful, the strength of those who labour, and the repose of the dead;\nWe thank thee for the timely blessings of the day, and humbly supplicate thy merciful protection all this night.\nBring us, we beseech thee, in safety to the morning hours;\nthrough him who died for us and rose again, thy Son, our Saviour Jesus Christ. Amen.","note":"An evening prayer for the household, from the Family Prayer of the 1928 book.","voice":"brian","source":{"name":"The Book of Common Prayer (1928, United States): Forms of Prayer to Be Used in Families","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-guidance","title":"In All Our Doubts and Uncertainties","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian","all"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["comfort","daily"],"text":"O God, by whom the meek are guided in judgment, and light riseth up in darkness for the godly;\nGrant us, in all our doubts and uncertainties, the grace to ask what thou wouldest have us to do;\nthat the Spirit of wisdom may save us from all false choices,\nand that in thy light we may see light, and in thy straight path may not stumble;\nthrough Jesus Christ our Lord. Amen.","note":"A prayer for guidance, good for a family facing hard medical choices.","voice":"jenny","source":{"name":"The Book of Common Prayer (1928, United States): Forms of Prayer to Be Used in Families","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-joy-in-creation","title":"For Joy in God's Creation","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian","nature"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["nature","gratitude","morning"],"text":"O heavenly Father, who hast filled the world with beauty;\nOpen, we beseech thee, our eyes to behold thy gracious hand in all thy works;\nthat rejoicing in thy whole creation, we may learn to serve thee with gladness;\nfor the sake of him by whom all things were made, thy Son, Jesus Christ our Lord. Amen.","note":"A short prayer of wonder, for a walk outdoors or a nature lover's memorial.","voice":"brian","source":{"name":"The Book of Common Prayer (1928, United States): Forms of Prayer to Be Used in Families","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-for-children","title":"For the Children","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["home","birth","blessing"],"text":"Almighty God, heavenly Father, who hast blessed us with the joy and care of children;\nGive us light and strength so to train them,\nthat they may love whatsoever things are true and pure and lovely and of good report,\nfollowing the example of their Saviour Jesus Christ. Amen.","note":"A parents' prayer, from the Family Prayer of the 1928 book.","voice":"jenny","source":{"name":"The Book of Common Prayer (1928, United States): Forms of Prayer to Be Used in Families","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-thanksgiving-childbirth","title":"A Thanksgiving after Childbirth","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["birth","gratitude"],"text":"O Almighty God, we give thee humble thanks for that thou hast been graciously pleased to preserve, through the great pain and peril of childbirth, this woman, thy servant, who desireth now to offer her praises and thanksgivings unto thee.\nGrant, we beseech thee, most merciful Father, that she, through thy help, may faithfully live according to thy will in this life present;\nand also may be partaker of everlasting glory in the life to come;\nthrough Jesus Christ our Lord. Amen.","note":"From the Thanksgiving of Women after Child-birth, for a mother and her new baby.","voice":"brian","source":{"name":"The Book of Common Prayer (1928, United States): The Thanksgiving of Women after Child-birth","url":"https://justus.anglican.org/resources/bcp/1928/"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-blessing-anglican-vigil","title":"A Blessing for an Evensong Vigil","by":"Grow With Grounded","year":2026,"trad":["episcopal"],"denom":["anglican"],"type":"blessing","occasion":["dying","evening","peace"],"text":"As the light fades, we gather the old words around you like a blanket.\nLighten our darkness, we pray, and fill this room with peace.\nMay you rest as the day rests, held and loved,\nand wake to a morning full of light.","note":"Grounded words to open a family's Evening Prayer at the bedside, drawing on the Prayer Book's evening collect.","voice":"jenny","source":{"name":"Grow With Grounded, written for the Grounded Readings Library (2026)","url":""},"rights":"grounded","pd":"Grounded's own words."}];
